{
  "command": "cat > /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/ref/ccmc/scripts/summary.py <<'EOF'
import sys, json
import numpy as np
import pandas as pd

root = sys.argv[1]
win = {"3I-Atlas": ("2025-12-03T12:04:00", "2025-12-04T10:12:00"), "earth": ("2025-11-20T00:00:00", "2025-12-06T00:00:00"), "stereoa": ("2025-11-20T00:00:00", "2025-12-06T00:00:00")}
out = {}
for body, (a, b) in win.items():
    for tag, run in [("", "cme"), ("_ambient", "ambient")]:
        d = pd.read_csv(f"{root}/timeseries/enlil_{body}{tag}.csv", parse_dates=["utc"])
        w = d[(d.utc >= a) & (d.utc < b)].copy()
        w["v_kms"] = np.sqrt(w.vr_kms ** 2 + w.vlon_kms ** 2 + w.vlat_kms ** 2)
        w["b_nT"] = np.sqrt(w.br_nT ** 2 + w.blon_nT ** 2 + w.blat_nT ** 2)
        r = {"start": a, "stop": b, "nrows": int(len(w))}
        for k in ["r_au", "lat_deg", "lon_heeq_deg", "n_cm3", "vr_kms", "v_kms", "nvr_cm2s", "T_K", "b_nT"]:
            r[k] = {"median": float(w[k].median()), "min": float(w[k].min()), "max": float(w[k].max())}
        out[f"{body}_{run}"] = r
json.dump(out, open(f"{root}/timeseries/summary_windows.json", "w"), indent=1)
for k, r in out.items():
    print(k, r["nrows"], {q: round(r[q]["median"], 4 if q in ("r_au",) else 3) for q in ["n_cm3", "vr_kms", "v_kms", "nvr_cm2s", "T_K", "b_nT"]})
EOF
cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/ref/ccmc && /home/scabot/miniconda3/bin/python3 -I scripts/summary.py "$PWD"",
  "description": "Write window summary JSON",
  "timeout": 300000
}

